#!/usr/bin/env python3
# =============================================================================
# Analyze AQM Simulation Results
# Parses FlentApplication JSON outputs, computes metrics, generates plots
# =============================================================================
#
# DATA SOURCES FOR EACH METRIC:
# -----------------------------
# All metrics are computed EXCLUSIVELY from FlentApplication's JSON output
# (generated by FlentApplication::StopApplication -> FillXValues -> ProcessRawValues).
#
# FlentApplication's JSON contains ONLY the forward data flows it explicitly
# creates and tracks via its own trace callbacks:
#   - TraceSentPacket     -> BulkSendApplication (TCP upload, forward data)
#   - TraceReceivedPacket -> PacketSink          (TCP download, forward data)
#   - TraceReceivedUdpPing-> UdpEchoClient       (UDP echo RTT)
#
# The JSON does NOT contain:
#   - TCP ACK flows (reverse direction)
#   - UDP echo replies as separate flows
#   - Any FlowMonitor-classified flows
#
# IMPORTANT: JSON flow names (keys in "results" object) differ by test type:
#   - tcp_upload / tcp_download: "TCP upload", "TCP download" (no DSCP suffix)
#   - rrul: "TCP upload BE", "TCP download BE", "TCP upload BK", "TCP download BK",
#           "TCP upload CS5", "TCP download CS5", "TCP upload EF", "TCP download EF"
#   - RTT: "Ping (ms) ICMP", "Ping (ms) UDP BE", "Ping (ms) UDP BK", "Ping (ms) UDP EF"
#   - NO UDP flows in JSON output (UDP echo replies not tracked separately)
#
# JSON structure (from FlentApplication):
# {
#   "metadata": {...},
#   "x_values": [0.1, 0.2, 0.3, ...],           # time steps (seconds)
#   "results": {
#     "TCP upload": [1.2, 1.3, 1.1, ...],        # goodput values (Mbps) per step
#     "TCP download": [2.1, 2.0, ...],
#     "Ping (ms) ICMP": [5.2, 5.1, ...],         # RTT values (ms) per step
#     ...
#   }
# }
#
# FlowMonitor output printed by the simulation is for debugging only;
# this analyzer never reads FlowMonitor XML.
#
# =============================================================================

import json
import glob
import os
import sys
import numpy as np
import pandas as pd
from collections import defaultdict

# Try to import matplotlib for plotting
try:
    import matplotlib
    matplotlib.use('Agg')  # Non-interactive backend
    import matplotlib.pyplot as plt
    HAS_MPL = True
except ImportError:
    HAS_MPL = False
    print("matplotlib not available - skipping plots")

# =============================================================================
# Jain's Fairness Index
# JFI = (sum(x_i))^2 / (n * sum(x_i^2))
# Returns value in [0, 1], where 1 = perfect fairness
# =============================================================================
def jains_fairness_index(values):
    """Compute Jain's Fairness Index for a list of values (e.g., per-flow throughput)."""
    if not values:
        return 0.0
    n = len(values)
    sum_vals = sum(values)
    sum_sq = sum(v * v for v in values)
    if sum_sq == 0:
        return 0.0
    return (sum_vals * sum_vals) / (n * sum_sq)


# =============================================================================
# Identify TCP flows in rrul test (8 flows per client: 4 upload + 4 download)
# FlentApplication rrul flow naming (from StartApplication):
#   "TCP upload BE", "TCP download BE", "TCP upload BK", "TCP download BK",
#   "TCP upload CS5", "TCP download CS5", "TCP upload EF", "TCP download EF"
# Simple tests: "TCP upload", "TCP download" (no DSCP)
# RTT flows: "Ping (ms) ICMP", "Ping (ms) UDP BE", "Ping (ms) UDP BK", "Ping (ms) UDP EF"
# =============================================================================
def is_tcp_rrul_flow(flow_name):
    """Check if flow name is one of the 8 TCP flows in rrul test."""
    # FlentApplication rrul uses "TCP upload X" and "TCP download X" with DSCP suffix
    tcp_prefixes = ("TCP upload ", "TCP download ")
    return flow_name.startswith(tcp_prefixes)


def is_tcp_simple_flow(flow_name):
    """Check if flow name is from tcp_upload or tcp_download test."""
    # Simple tests use exact names "TCP upload" and "TCP download"
    return flow_name in ("TCP upload", "TCP download")


def is_tcp_flow(flow_name, test):
    """Check if flow name is a TCP flow for the given test."""
    if test == 'rrul':
        return is_tcp_rrul_flow(flow_name)
    else:
        return is_tcp_simple_flow(flow_name)


def is_rtt_flow(flow_name):
    """Check if flow name is an RTT flow (ICMP or UDP ping)."""
    return flow_name.startswith("Ping (ms)")


# =============================================================================
# Parse Flent JSON output (SOURCE: FlentApplication JSON only)
# =============================================================================
def parse_flent_json(json_path):
    """Extract key metrics from FlentApplication JSON output.

    Source: FlentApplication JSON (generated by ProcessRawValues()).
    Contains ONLY forward data flows tracked by FlentApplication's own callbacks.
    JSON structure:
    {
      "metadata": {...},
      "x_values": [...],  # time steps
      "results": {
        "TCP upload": [...],  # interpolated goodput values (Mbps) per step
        "Ping (ms) ICMP": [...],  # RTT values (ms) per step
        ...
      }
    }
    """
    with open(json_path, 'r') as f:
        data = json.load(f)

    results = {
        'test_name': data.get('metadata', {}).get('NAME', 'unknown'),
        'duration': data.get('metadata', {}).get('LENGTH', 0),
        'flows': {}
    }

    x_values = data.get('x_values', [])
    results_data = data.get('results', {})

    for flow_name, flow_values in results_data.items():
        flow_result = {}

        # flow_values is an array of interpolated values (one per x_value)
        # Values can be null if interpolation failed
        valid_values = [v for v in flow_values if v is not None]

        if not valid_values:
            continue

        if is_rtt_flow(flow_name):
            # RTT flow - values are in ms
            flow_result['mean_rtt_ms'] = np.mean(valid_values)
            flow_result['median_rtt_ms'] = np.median(valid_values)
            flow_result['p99_rtt_ms'] = np.percentile(valid_values, 99) if len(valid_values) > 1 else valid_values[0]
            flow_result['min_rtt_ms'] = np.min(valid_values)
            flow_result['max_rtt_ms'] = np.max(valid_values)
            flow_result['rtt_series'] = valid_values
        else:
            # TCP flow - values are goodput in Mbps
            flow_result['mean_goodput_mbps'] = np.mean(valid_values)
            flow_result['median_goodput_mbps'] = np.median(valid_values)
            flow_result['goodput_series'] = valid_values

        results['flows'][flow_name] = flow_result

    return results


# =============================================================================
# Parse all results in a directory
# =============================================================================
def parse_all_results(results_dir):
    """Walk results directory and parse all Flent JSON files."""
    all_results = []

    # Find all JSON files
    json_files = glob.glob(os.path.join(results_dir, '**', '*.json'), recursive=True)

    for json_file in json_files:
        try:
            # Extract parameters from path
            rel_path = os.path.relpath(json_file, results_dir)
            parts = rel_path.split(os.sep)

            qdisc = test = seed = client = None

            # Case 1: Files in subdirectory {QDISC}_{TEST}_s{SEED}/file.json
            if len(parts) >= 2:
                dir_name = parts[-2]
                file_name = parts[-1]
                dir_parts = dir_name.split('_')
                if len(dir_parts) >= 3:
                    qdisc = dir_parts[0]
                    test = dir_parts[1]
                    seed = dir_parts[2].replace('s', '')
            # Case 2: Files directly in results_dir (current scenario)
            elif len(parts) == 1:
                file_name = parts[0]
                # Parse from filename: flent-{QDISC}-{TEST}-client{N}-s{SEED}.json
                # Remove .json and split by '-'
                name_parts = file_name.replace('.json', '').split('-')
                # Expected: ['flent', 'FqCoDel', 'rrul', 'client0', 's1']
                if len(name_parts) >= 5 and name_parts[0] == 'flent':
                    qdisc = name_parts[1]
                    test = name_parts[2]
                    # client part: 'client0' -> '0'
                    if name_parts[3].startswith('client'):
                        client = name_parts[3].replace('client', '')
                    # seed part: 's1' -> '1'
                    if name_parts[4].startswith('s'):
                        seed = name_parts[4].replace('s', '')

            if qdisc is None or test is None or seed is None:
                print(f"Warning: Could not parse parameters from {rel_path}")
                continue

            parsed = parse_flent_json(json_file)
            parsed['queue_disc'] = qdisc
            parsed['test'] = test
            parsed['seed'] = int(seed)
            parsed['client'] = client if client is not None else '0'
            parsed['source_file'] = json_file

            all_results.append(parsed)
        except Exception as e:
            print(f"Error parsing {json_file}: {e}")

    return all_results


# =============================================================================
# Aggregate metrics across clients/seeds
# =============================================================================
def aggregate_results(all_results):
    """Aggregate per-flow metrics into per-run, then per-configuration summaries.

    All metrics derived from Flent JSON (forward data flows only).
    """
    # Group by (queue_disc, test, seed)
    runs = defaultdict(list)
    for r in all_results:
        key = (r['queue_disc'], r['test'], r['seed'])
        runs[key].append(r)

    summary = []

    for (qdisc, test, seed), clients in runs.items():
        # Expected flow counts per client (from FlentApplication source):
        #   tcp_upload:      1 TCP flow per client  -> 3 TCP flows total (nClients=3)
        #   tcp_download:    1 TCP flow per client  -> 3 TCP flows total (nClients=3)
        #   rrul:            8 TCP flows (4 up + 4 down) per client
        #                                              -> 24 TCP total (nClients=3)
        #   UDP flows: NOT present in JSON output

        # Collect per-flow metrics and per-client aggregates (SOURCE: Flent JSON)
        all_tcp_goodputs = []          # All TCP flow goodputs (for flow-level JFI)
        all_client_tcp_totals = []     # Per-client aggregate TCP throughput (for client-level JFI)
        all_rtts = []                  # All RTT values (ICMP + UDP)
        all_icmp_rtts = []             # ICMP RTT only

        for client in clients:
            client_tcp_total = 0.0
            client_tcp_count = 0

            for flow_name, flow_data in client['flows'].items():
                if 'mean_goodput_mbps' in flow_data:
                    # TCP flow
                    if is_tcp_flow(flow_name, test):
                        gp = flow_data['mean_goodput_mbps']
                        all_tcp_goodputs.append(gp)
                        client_tcp_total += gp
                        client_tcp_count += 1

                if 'mean_rtt_ms' in flow_data:
                    # RTT flow (ICMP or UDP ping)
                    rtt = flow_data['mean_rtt_ms']
                    all_rtts.append(rtt)
                    if flow_name == "Ping (ms) ICMP":
                        all_icmp_rtts.append(rtt)

            # Store per-client aggregate TCP throughput (for client-level JFI)
            if client_tcp_count > 0:
                all_client_tcp_totals.append(client_tcp_total)

        # Compute aggregates
        run_summary = {
            'queue_disc': qdisc,
            'test': test,
            'seed': seed,
            'n_tcp_flows': len(all_tcp_goodputs),
            'n_clients': len(all_client_tcp_totals),
        }

        if all_tcp_goodputs:
            run_summary['mean_tcp_throughput_mbps'] = np.mean(all_tcp_goodputs)
            run_summary['total_tcp_throughput_mbps'] = sum(all_tcp_goodputs)

            # Flow-level JFI: fairness across all TCP flows (SOURCE: Flent JSON goodput)
            #   rrul: 24 TCP flows (8 per client × 3 clients)
            #   tcp_upload/tcp_download: 3 TCP flows (1 per client × 3 clients)
            run_summary['jfi_flow_tcp_throughput'] = jains_fairness_index(all_tcp_goodputs)

            # Client-level JFI: fairness across clients (SOURCE: Flent JSON goodput)
            #   Uses per-client aggregate TCP throughput (sum of that client's TCP flows)
            #   3 clients -> 3 values
            if len(all_client_tcp_totals) > 1:
                run_summary['jfi_client_tcp_throughput'] = jains_fairness_index(all_client_tcp_totals)
            else:
                run_summary['jfi_client_tcp_throughput'] = 1.0  # Single client is trivially fair

        if all_rtts:
            run_summary['mean_rtt_ms'] = np.mean(all_rtts)
            run_summary['median_rtt_ms'] = np.median(all_rtts)
            run_summary['p99_rtt_ms'] = np.percentile(all_rtts, 99) if len(all_rtts) > 1 else all_rtts[0]

        if all_icmp_rtts:
            run_summary['mean_icmp_rtt_ms'] = np.mean(all_icmp_rtts)
            run_summary['p99_icmp_rtt_ms'] = np.percentile(all_icmp_rtts, 99) if len(all_icmp_rtts) > 1 else all_icmp_rtts[0]

        summary.append(run_summary)

    return summary


# =============================================================================
# Compute statistics across seeds
# =============================================================================
def compute_statistics(summary):
    """Compute mean ± std across seeds for each (queue_disc, test) combination."""
    df = pd.DataFrame(summary)

    if df.empty:
        return pd.DataFrame()

    # Group by queue_disc and test
    grouped = df.groupby(['queue_disc', 'test'])

    stats = []
    for (qdisc, test), group in grouped:
        row = {'queue_disc': qdisc, 'test': test, 'n_seeds': len(group)}

        for col in ['mean_tcp_throughput_mbps', 'total_tcp_throughput_mbps',
                     'jfi_flow_tcp_throughput', 'jfi_client_tcp_throughput',
                     'mean_rtt_ms', 'median_rtt_ms', 'p99_rtt_ms',
                     'mean_icmp_rtt_ms', 'p99_icmp_rtt_ms']:
            if col in group.columns:
                vals = group[col].dropna()
                if len(vals) > 0:
                    row[f'{col}_mean'] = vals.mean()
                    row[f'{col}_std'] = vals.std() if len(vals) > 1 else 0.0
                    row[f'{col}_min'] = vals.min()
                    row[f'{col}_max'] = vals.max()

        stats.append(row)

    return pd.DataFrame(stats)


# =============================================================================
# Generate comparison plots
# =============================================================================
def generate_plots(stats_df, output_dir):
    """Generate comparison plots for each metric."""
    if not HAS_MPL:
        return

    os.makedirs(output_dir, exist_ok=True)

    # Define queue disc order for consistent plotting
    qdisc_order = ['PfifoFast', 'FqCoDel', 'FqPie', 'FqCobalt']
    colors = {'PfifoFast': '#e74c3c', 'FqCoDel': '#2ecc71', 'FqPie': '#3498db', 'FqCobalt': '#9b59b6'}

    # Metrics to plot
    metrics = [
        ('total_tcp_throughput_mbps_mean', 'Total TCP Throughput (Mbps)', 'throughput'),
        ('mean_rtt_ms_mean', 'Mean RTT (ms)', 'rtt'),
        ('mean_icmp_rtt_ms_mean', 'Mean ICMP RTT (ms)', 'icmp_rtt'),
        ('jfi_flow_tcp_throughput_mean', "Jain's Fairness Index (Flow-level)", 'jfi_flow'),
        ('jfi_client_tcp_throughput_mean', "Jain's Fairness Index (Client-level)", 'jfi_client'),
    ]

    tests = stats_df['test'].unique()

    for test in tests:
        test_data = stats_df[stats_df['test'] == test].set_index('queue_disc')
        test_data = test_data.reindex(qdisc_order)  # Ensure order

        fig, axes = plt.subplots(2, 3, figsize=(15, 10))
        axes = axes.flatten()

        for idx, (metric_col, metric_label, metric_name) in enumerate(metrics):
            ax = axes[idx]
            if metric_col not in test_data.columns:
                ax.text(0.5, 0.5, f'{metric_label}\n(not available for {test})', ha='center', va='center')
                ax.set_title(metric_label)
                continue

            means = test_data[metric_col]
            stds = test_data.get(f'{metric_col}_std', pd.Series(0, index=means.index))

            x_pos = range(len(qdisc_order))
            bars = ax.bar(x_pos, means, yerr=stds, capsize=5,
                          color=[colors.get(q, '#7f8c8d') for q in qdisc_order],
                          edgecolor='black', alpha=0.8)
            ax.set_xticks(x_pos)
            ax.set_xticklabels(qdisc_order, rotation=15)
            ax.set_ylabel(metric_label)
            ax.set_title(f'{metric_label} - {test}')
            ax.grid(axis='y', alpha=0.3)

            # Add value labels on bars
            for i, (bar, mean) in enumerate(zip(bars, means)):
                if not np.isnan(mean):
                    std_val = stds.iloc[i] if i < len(stds) and not np.isnan(stds.iloc[i]) else 0
                    ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + std_val,
                           f'{mean:.2f}', ha='center', va='bottom', fontsize=8)

        # Hide unused subplot
        if len(metrics) < len(axes):
            axes[-1].set_visible(False)

        plt.suptitle(f'AQM Comparison: {test.upper()} Test', fontsize=14)
        plt.tight_layout()
        plt.savefig(os.path.join(output_dir, f'comparison_{test}.png'), dpi=150)
        plt.close()

    # Combined plot: all tests, one metric per figure
    for metric_col, metric_label, metric_name in metrics:
        if metric_col not in stats_df.columns:
            continue

        fig, ax = plt.subplots(figsize=(10, 6))

        x = np.arange(len(qdisc_order))
        width = 0.25
        multiplier = 0

        for test in tests:
            test_data = stats_df[stats_df['test'] == test].set_index('queue_disc')
            test_data = test_data.reindex(qdisc_order)
            means = test_data[metric_col]
            stds = test_data.get(f'{metric_col}_std', pd.Series(0, index=means.index))

            offset = width * multiplier
            bars = ax.bar(x + offset, means, width, yerr=stds, capsize=3,
                          label=test, color=plt.cm.Set2(multiplier), alpha=0.8,
                          edgecolor='black')
            multiplier += 1

        ax.set_xticks(x + width)
        ax.set_xticklabels(qdisc_order)
        ax.set_ylabel(metric_label)
        ax.set_title(f'{metric_label} by AQM and Test')
        ax.legend()
        ax.grid(axis='y', alpha=0.3)

        plt.tight_layout()
        plt.savefig(os.path.join(output_dir, f'{metric_name}_all_tests.png'), dpi=150)
        plt.close()

    print(f"Plots saved to {output_dir}")


# =============================================================================
# Main
# =============================================================================
def main():
    if len(sys.argv) < 2:
        print("Usage: python3 analyze_results.py <results_directory> [output_csv] [plot_dir]")
        sys.exit(1)

    results_dir = sys.argv[1]
    output_csv = sys.argv[2] if len(sys.argv) > 2 else 'aqm_analysis_results.csv'
    plot_dir = sys.argv[3] if len(sys.argv) > 3 else 'plots'

    print(f"Analyzing results in: {results_dir}")

    # Parse all JSON files (SOURCE: Flent JSON only)
    all_results = parse_all_results(results_dir)
    print(f"Parsed {len(all_results)} client result files")

    if not all_results:
        print("ERROR: No valid JSON files found. Check directory structure and file naming.")
        print(f"Expected files like: flent-{{QDISC}}-{{TEST}}-client{{N}}-s{{SEED}}.json")
        print(f"Or in subdirectories: {{QDISC}}_{{TEST}}_s{{SEED}}/flent-...")
        sys.exit(1)

    # Aggregate per-run (SOURCE: Flent JSON only)
    run_summary = aggregate_results(all_results)
    print(f"Aggregated into {len(run_summary)} runs")

    if not run_summary:
        print("ERROR: No runs could be aggregated from parsed files.")
        sys.exit(1)

    # Statistics across seeds
    stats_df = compute_statistics(run_summary)
    print(f"Computed statistics for {len(stats_df)} configurations")

    if stats_df.empty:
        print("ERROR: No statistics computed.")
        sys.exit(1)

    # Save CSV
    stats_df.to_csv(output_csv, index=False)
    print(f"Results saved to: {output_csv}")

    # =============================================================================
    # DETAILED PER-SEED BREAKDOWN (matches execute.txt Command 3)
    # =============================================================================
    print("\n" + "=" * 60)
    print("DETAILED PER-SEED METRIC VALUES (all key metrics)")
    print("=" * 60)

    run_df = pd.DataFrame(run_summary)
    qdisc_order = ['PfifoFast', 'FqCoDel', 'FqPie', 'FqCobalt']
    test_order = ['tcp_upload', 'tcp_download', 'rrul']
    key_metrics = [
        'total_tcp_throughput_mbps',
        'mean_rtt_ms',
        'mean_icmp_rtt_ms',
        'jfi_flow_tcp_throughput',
        'jfi_client_tcp_throughput'
    ]

    # Print column detection info
    qdisc_col = 'queue_disc'
    test_col = 'test'
    seed_col = 'seed'
    print(f'Queue disc column: {qdisc_col}')
    print(f'Test column: {test_col}')
    print(f'Seed column: {seed_col}')
    if qdisc_col in run_df.columns:
        print(f'Unique queue_discs: {sorted(run_df[qdisc_col].unique())}')
        print(f'Unique tests: {sorted(run_df[test_col].unique())}')
        print(f'Unique seeds: {sorted(run_df[seed_col].unique())}')
    print()

    for q in qdisc_order:
        for t in test_order:
            sub = run_df[(run_df[qdisc_col] == q) & (run_df[test_col] == t)]
            if len(sub) == 0:
                print(f'{q:12s} {t:14s}: NO DATA')
                continue
            print(f'{q:12s} {t:14s}: n={len(sub)} seeds')
            for m in key_metrics:
                if m in sub.columns:
                    means = sub[m].values
                    stds = np.zeros_like(means)  # per-seed std not applicable, but keep format
                    print(f'  {m:35s}: {means}')
                    if np.all(means == means[0]) and len(means) > 1:
                        print(f'  {"std":35s}: ALL ZERO (identical seeds!)')
            print()

    # Link utilization calculation
    print("=" * 60)
    print("LINK UTILIZATION (throughput / bottleneck_rate)")
    print("=" * 60)
    BOTTLENECK_RATE = 10.0  # Mbps
    for q in qdisc_order:
        for t in test_order:
            sub = run_df[(run_df[qdisc_col] == q) & (run_df[test_col] == t)]
            if len(sub) == 0:
                continue
            if 'total_tcp_throughput_mbps' in sub.columns:
                mean_throughput = sub['total_tcp_throughput_mbps'].mean()
                utilization = (mean_throughput / BOTTLENECK_RATE) * 100
                print(f'{q:12s} {t:14s}: {mean_throughput:6.2f} Mbps  ({utilization:5.1f}% of {BOTTLENECK_RATE} Mbps)')

    # Print summary table
    print("\n=== Summary (mean ± std across seeds) ===")
    pd.set_option('display.max_columns', None)
    pd.set_option('display.width', 200)
    print_cols = ['queue_disc', 'test', 'n_seeds',
                  'total_tcp_throughput_mbps_mean', 'total_tcp_throughput_mbps_std',
                  'mean_rtt_ms_mean', 'mean_rtt_ms_std',
                  'mean_icmp_rtt_ms_mean', 'mean_icmp_rtt_ms_std',
                  'jfi_flow_tcp_throughput_mean', 'jfi_flow_tcp_throughput_std',
                  'jfi_client_tcp_throughput_mean', 'jfi_client_tcp_throughput_std']
    print_cols = [c for c in print_cols if c in stats_df.columns]
    print(stats_df[print_cols].to_string(index=False))

    # Generate plots
    if HAS_MPL:
        generate_plots(stats_df, plot_dir)
    else:
        print("\nSkipping plots (matplotlib not installed)")


if __name__ == '__main__':
    main()